[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$HtmlPath,[Parameter(Mandatory=$true)][string]$OutputPath,[string]$BaselineRoot='ES/Output/WebPageStudio/visual-baselines')
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\')+'\';$html=(Resolve-Path $HtmlPath).Path;if(-not $html.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){throw 'HtmlPath must remain under project root.'};$edge=@('C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe','C:\Program Files\Microsoft\Edge\Application\msedge.exe')|Where-Object{Test-Path $_}|Select-Object -First 1;if(-not $edge){throw 'Local Edge is required.'}
$baseRoot=Join-Path $root $BaselineRoot;New-Item -ItemType Directory $baseRoot -Force|Out-Null;$run=Join-Path (Split-Path $html) ('.visual-matrix-'+[guid]::NewGuid().ToString('N').Substring(0,12));New-Item -ItemType Directory $run|Out-Null;$rows=@();$profiles=@(@{id='desktop';w=1440;h=900},@{id='mobile';w=390;h=844});$themes=@('dark','light','forced-colors')
foreach($p in $profiles){foreach($t in $themes){$name="$($p.id)-$t-default";$temp=Join-Path $run "$name.html";$css=if($t -eq 'dark'){'<style>:root{color-scheme:dark}</style>'}elseif($t -eq 'light'){'<style>:root{--ink:#172021!important;--muted:#536562!important;--bg:#f4f7f5!important;--panel:#fff!important;--line:#c8d6d2!important;--cyan:#087f78!important;--lime:#8ab51f!important;--pink:#b63d5a!important;color-scheme:light}</style>'}else{'<style>*{forced-color-adjust:none!important}:root{--ink:CanvasText!important;--muted:GrayText!important;--bg:Canvas!important;--panel:Canvas!important;--line:ButtonText!important;--cyan:LinkText!important;--lime:Highlight!important;--pink:Mark!important;color-scheme:normal}</style>'};$src=Get-Content $html -Raw -Encoding UTF8;$src=$src.Replace('</head>',$css+'</head>');[IO.File]::WriteAllText($temp,$src,[Text.UTF8Encoding]::new($false));$shot=Join-Path $run "$name.png";$args="--headless=new --disable-gpu --disable-extensions --disable-background-networking --disable-component-update --disable-sync --disable-default-apps --no-first-run --user-data-dir=$run\$name-profile --window-size=$($p.w),$($p.h) --screenshot=$shot --hide-scrollbars $(([Uri]$temp).AbsoluteUri)";$proc=Start-Process $edge -ArgumentList $args -PassThru -WindowStyle Hidden -Wait;$relBase=Join-Path $baseRoot "$name.png";$comparison='baseline-created';$diff=$null;if(Test-Path $relBase){$candidateHash=(Get-FileHash $shot -Algorithm SHA256).Hash.ToLowerInvariant();$baselineHash=(Get-FileHash $relBase -Algorithm SHA256).Hash.ToLowerInvariant();$comparison=if($candidateHash -eq $baselineHash){'passed'}else{'review'};$diff=if($candidateHash -eq $baselineHash){0}else{$null}}else{Copy-Item $shot $relBase};$rows+= [ordered]@{id=$name;profile=$p.id;theme=$t;status=$comparison;exitCode=$proc.ExitCode;screenshotPath=$shot.Replace($root,'').Replace('\','/');baselinePath=$relBase.Replace($root,'').Replace('\','/');screenshotHash=(Get-FileHash $shot -Algorithm SHA256).Hash.ToLowerInvariant();baselineHash=(Get-FileHash $relBase -Algorithm SHA256).Hash.ToLowerInvariant();diffPixels=$diff;emulation='temporary-local-css'} }}
$o=[ordered]@{schemaVersion=1;recordType='WebPageStudioVisualMatrixRuntimeReceipt';status=if(@($rows|Where-Object{$_.status -in @('review','failed')}).Count){'review'}else{'passed'};runtimeStatus='runtime-passed';matrix=[ordered]@{profiles=@('desktop','mobile');themes=$themes;states=@('default');};captures=$rows;nonClaims=@('forced-colors is CSS emulation, not OS accessibility mode','baseline creation is not human visual approval','hash equality does not prove cross-browser equivalence')};$out=Join-Path $root $OutputPath;New-Item -ItemType Directory (Split-Path $out) -Force|Out-Null;[IO.File]::WriteAllText($out,($o|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$o|ConvertTo-Json -Depth 10
